const fs = require("fs");
const path = require("path");

function walk(dir) {
  let results = [];
  const list = fs.readdirSync(dir);
  list.forEach(file => {
    file = path.join(dir, file);
    const stat = fs.statSync(file);
    if (stat && stat.isDirectory()) {
      results = results.concat(walk(file));
    } else if (file.endsWith(".js")) {
      results.push(file);
    }
  });
  return results;
}

const files = walk("scripts_inspect/files");
for (const file of files) {
  const content = fs.readFileSync(file, "utf8");
  const lines = content.split("\n");
  // Look for any string containing /api/ or fetch or cal.boardy.ai or whatsapp.boardy.ai
  const matches = content.match(/https?:\/\/[^\s"'`]+|\/api\/[^\s"'`]+/g) || [];
  const unique = new Set(matches.filter(m => m.includes("boardy.ai") || m.startsWith("/api/")));
  if (unique.size > 0) {
    console.log(file, Array.from(unique));
  }
}

